            const menuGap = 8;
            const hostRect = host.getBoundingClientRect();
            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;
            const menuWidth = Math.min(208, viewportWidth - (viewportPadding * 2));
            const naturalMenuHeight = variantMenu.scrollHeight;
            const spaceAbove = hostRect.top - menuGap - viewportPadding;
            const spaceBelow = viewportHeight - hostRect.bottom - menuGap - viewportPadding;
            const placeBelow = spaceBelow >= Math.min(naturalMenuHeight, 180) || spaceBelow >= spaceAbove;
            const availableHeight = Math.max(96, placeBelow ? spaceBelow : spaceAbove);
            const menuHeight = Math.min(naturalMenuHeight, availableHeight);
