        if (!langForm || !langForm.parentNode) {
            return false;
        }

        const host = createThemeSwitchHost('gf-theme-switch', {
            marginLeft: '8px'
        });

        if (!host) {
            return Boolean(document.getElementById('gf-theme-switch'));
        }

        langForm.parentNode.insertBefore(host, langForm.nextSibling);
        return true;
