    const getUserNavI18n = (locale) => {
        const exactLocale = USER_NAV_I18N[locale] || {};
        const primaryLocale = USER_NAV_I18N[String(locale || '').split('-')[0]] || {};
        const exactWideLayout = WIDE_LAYOUT_I18N[locale] || {};
        const primaryWideLayout = WIDE_LAYOUT_I18N[String(locale || '').split('-')[0]] || {};
        return {
            ...USER_NAV_I18N.en,
            ...primaryLocale,
            ...exactLocale,
            density: {
                ...USER_NAV_I18N.en.density,
                ...primaryLocale.density,
                ...exactLocale.density,
                ...primaryWideLayout,
                ...exactWideLayout
            }
        };
    };

    dependencyNoticeReady = true;
    if (dependencyWarnings.size) showDependencyNotice();

    const normalizeFavoriteSetName = (value) => String(value || '').trim().toLocaleLowerCase();
    const isFavoriteSetName = (value) => {
        const normalizedValue = normalizeFavoriteSetName(value);
        if (!normalizedValue) {
            return false;
        }

        return FAVORITE_SET_NAME_PATTERN.test(normalizedValue)
            || Object.values(USER_NAV_I18N).some((i18n) => {
                const favoriteSetName = normalizeFavoriteSetName(i18n.favoriteSetName);
                return favoriteSetName && (normalizedValue === favoriteSetName || normalizedValue.includes(favoriteSetName));
            });
    };

    const FAVORITES_NAV_SHORTCUT_ATTR = 'data-gfplus-favorites-shortcut';
    const initFavoritesNavShortcut = () => {
        if (!extractCurrentUserProfilePath()) {
            return false;
        }

        const targets = [
            {
                menu: document.querySelector('#site-nav > nav > li.with-submenu > nav'),
                className: 'gf-favorites-nav-shortcut',
                insert: (menu, item) => menu.prepend(item)
            },
            {
                menu: document.getElementById('gf-mobile-secondary-nav'),
                className: 'gf-favorites-nav-shortcut gf-mobile-favorites-nav-shortcut',
                insert: (menu, item) => {
                    const divider = menu.querySelector(':scope > .gf-mobile-secondary-divider');
                    divider ? divider.after(item) : menu.prepend(item);
                }
            }
        ].filter(({ menu }) => menu && !menu.hasAttribute(FAVORITES_NAV_SHORTCUT_ATTR));

        if (!targets.length) {
            return true;
        }

        targets.forEach(({ menu }) => menu.setAttribute(FAVORITES_NAV_SHORTCUT_ATTR, 'loading'));
        void resolveFavoriteSetUrl()
            .then((favoriteSetUrl) => {
                const profileLocale = extractCurrentUserProfilePath()?.match(/^\/([^/]+)\//)?.[1];
                const locale = profileLocale || getCurrentLocale();
                targets.forEach(({ menu, className, insert }) => {
                    if (!favoriteSetUrl || !menu.isConnected) {
                        menu.setAttribute(FAVORITES_NAV_SHORTCUT_ATTR, 'unavailable');
                        return;
                    }

                    const shortcutItem = document.createElement('li');
                    shortcutItem.className = className;

                    const shortcutLink = document.createElement('a');
                    shortcutLink.href = favoriteSetUrl;
                    shortcutLink.textContent = getUserNavI18n(locale).favoriteSetName;

                    shortcutItem.appendChild(shortcutLink);
                    insert(menu, shortcutItem);
                    menu.setAttribute(FAVORITES_NAV_SHORTCUT_ATTR, 'ready');
                });
            })
            .catch(() => {
                targets.forEach(({ menu }) => menu.setAttribute(FAVORITES_NAV_SHORTCUT_ATTR, 'unavailable'));
            });

        return true;
    };

    // Profile Control Panel
    const CONTROL_PANEL_STYLE_ID = 'gfplus-control-panel-style';
    const CONTROL_PANEL_LAYOUT_KEY = 'gfplus-control-panel-layout';
    const CONTROL_PANEL_CSS = `
        #control-panel > header { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
        #control-panel > header > h3 { margin-block: 0; }
        #control-panel .gf-control-layout-toggle {
            display: inline-flex; align-items: center; justify-content: center;
            flex: 0 0 32px; width: 32px; min-width: 32px; height: 32px;
            box-sizing: border-box; margin: 0; padding: 6px;
            border: 1px solid var(--content-border-color); border-radius: 6px;
            background: var(--content-background-color); color: var(--link-color);
            box-shadow: none; cursor: pointer;
        }
        #control-panel .gf-control-layout-toggle:hover {
            background: color-mix(in srgb, var(--link-color) 10%, var(--content-background-color));
        }
        #control-panel .gf-control-layout-toggle:focus-visible {
            outline: 2px solid var(--link-color); outline-offset: 3px;
        }
        #control-panel .gf-control-layout-toggle svg { width: 18px; height: 18px; }
        #user-control-panel[data-gfplus-control-panel] {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
            gap: 10px;
            list-style: none;
            padding: 0;
            margin: 0;
        }
        #user-control-panel[data-gfplus-control-panel] > li {
            display: flex;
            min-width: 0;
            padding: 0;
            margin: 0;
            list-style: none;
        }
        #user-control-panel[data-gfplus-control-panel] > li > a {
            display: flex;
            align-items: center;
            gap: 10px;
            box-sizing: border-box;
            width: 100%;
            min-height: 58px;
            padding: 12px;
            border: 1px solid var(--content-border-color);
            border-radius: 10px;
            background: var(--content-background-color);
            color: var(--overall-text-color);
            font-size: .9rem;
            font-weight: 600;
            line-height: 1.4;
            overflow-wrap: anywhere;
            text-decoration: none;
            transition: background-color .16s ease, border-color .16s ease;
        }
        #user-control-panel[data-gfplus-control-panel] > li > a:hover {
            background: color-mix(in srgb, var(--link-color) 8%, var(--content-background-color));
            border-color: var(--link-color);
        }
        #user-control-panel[data-gfplus-control-panel] > li > a:focus-visible {
            outline: 2px solid var(--link-color);
            outline-offset: 3px;
        }
        #user-control-panel [data-gfplus-control-icon] {
            width: 20px;
            height: 20px;
            flex: 0 0 20px;
            color: var(--link-color);
        }
        #user-control-panel [data-gfplus-control-danger] {
            --link-color: #b91c1c;
        }
        html[data-theme="dark"] #user-control-panel [data-gfplus-control-danger] {
            --link-color: #f87171;
        }
        #user-control-panel[data-gfplus-control-layout="list"] {
            grid-template-columns: minmax(0, 1fr);
            gap: 4px;
        }
        #user-control-panel[data-gfplus-control-layout="list"] > li > a {
            width: fit-content;
            max-width: 100%;
            min-height: 30px;
            padding: 3px 0;
            border: 0;
            border-radius: 0;
            background: none;
            box-shadow: none;
            color: var(--link-color);
            font-weight: 500;
        }
        #user-control-panel[data-gfplus-control-layout="list"] > li > a:hover {
            background: none;
            text-decoration: underline;
        }
        #user-control-panel[data-gfplus-control-layout="list"] > li[data-gfplus-group-start] {
            margin-top: 4px;
            padding-top: 4px;
            border-top: 1px solid var(--content-border-color);
        }
        @media (max-width: 600px) {
            #user-control-panel[data-gfplus-control-panel] {
                grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr));
                gap: 6px;
            }
            #user-control-panel[data-gfplus-control-panel] > li > a {
                min-height: 44px;
                padding: 8px;
                gap: 8px;
                font-size: .82rem;
                border-radius: 7px;
            }
            #user-control-panel [data-gfplus-control-icon] {
                width: 18px; height: 18px; flex-basis: 18px;
            }
            #user-control-panel[data-gfplus-control-layout="list"] {
                grid-template-columns: minmax(0, 1fr);
                gap: 3px;
            }
            #user-control-panel[data-gfplus-control-layout="list"] > li > a {
                min-height: 30px;
                padding: 3px 0;
                border-radius: 0;
            }
        }
    `;

    const CONTROL_PANEL_ICON_PATHS = {
        script: '<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/>',
        style: '<path d="m14 4 6 6M4 20l4-1L21 6a2.1 2.1 0 0 0-3-3L5 16l-1 4Z"/>',
        set: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M17.5 14v7M14 17.5h7"/>',
        import: '<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
        webhook: '<circle cx="12" cy="5" r="3"/><circle cx="5" cy="18" r="3"/><circle cx="19" cy="18" r="3"/><path d="m10.5 7.5-4 8m7-8 4 8M8 18h8"/>',
        account: '<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
        signIn: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
        bell: '<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 13h4"/>',
        settings: '<path d="M4 7h9m4 0h3M4 17h3m4 0h9"/><circle cx="15" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',
        trash: '<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15m-9 4v7m4-7v7"/>',
        signOut: '<path d="M9 3H4v18h5m5-14 5 5-5 5m-5-5h10"/>',
        fallback: '<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m10 8 4 4-4 4"/>'
    };

    const getControlPanelIcon = (link) => {
        const url = new URL(link.href, window.location.href);
        const path = url.pathname.replace(/\/$/, '');
        if (path.endsWith('/script_versions/new')) return url.searchParams.get('language') === 'css' ? 'style' : 'script';
        if (path.endsWith('/sets/new')) return 'set';
        if (path.endsWith('/import')) return 'import';
        if (path.endsWith('/webhook-info')) return 'webhook';
        if (path.endsWith('/users/edit')) return 'account';
        if (path.endsWith('/edit_sign_in')) return 'signIn';
        if (path.endsWith('/notifications')) return 'bell';
        if (path.endsWith('/notification_settings')) return 'settings';
        if (/\/(delete_info|delete_account|edit_account_deletion)$/.test(path)) return 'trash';
        if (path.endsWith('/sign_out')) return 'signOut';
        return 'fallback';
    };

    const initControlPanelEnhancements = () => {
        const panel = document.getElementById('user-control-panel');
        if (!HAS_BASE_THEME || !panel) return;
        if (!document.getElementById(CONTROL_PANEL_STYLE_ID)) {
            const style = document.createElement('style');
            style.id = CONTROL_PANEL_STYLE_ID;
            style.textContent = CONTROL_PANEL_CSS;
            appendStyle(style);
        }
        panel.querySelectorAll(':scope > li > a[href]').forEach((link) => {
            if (link.querySelector('[data-gfplus-control-icon]')) return;
            const name = getControlPanelIcon(link);
            const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            icon.setAttribute('viewBox', '0 0 24 24');
            icon.setAttribute('fill', 'none');
            icon.setAttribute('stroke', 'currentColor');
            icon.setAttribute('stroke-width', '1.8');
            icon.setAttribute('stroke-linecap', 'round');
            icon.setAttribute('stroke-linejoin', 'round');
            icon.setAttribute('aria-hidden', 'true');
            icon.setAttribute('focusable', 'false');
            icon.setAttribute('data-gfplus-control-icon', name);
            icon.innerHTML = CONTROL_PANEL_ICON_PATHS[name];
            // Decorate the existing link: keep its locale, event handlers and data-method.
            link.prepend(icon);
            if (name === 'trash' || name === 'signOut') link.setAttribute('data-gfplus-control-danger', 'true');
        });
        panel.setAttribute('data-gfplus-control-panel', 'true');
        const header = panel.closest('#control-panel')?.querySelector(':scope > header');
        if (!header || header.querySelector('.gf-control-layout-toggle')) return;
        const originalItems = Array.from(panel.children);
        const groups = [
            ['script', 'style', 'set', 'import', 'webhook'],
            ['account', 'signIn'],
            ['bell', 'settings'],
            ['signOut', 'trash']
        ];
        const order = groups.flat();
        const iconFor = (item) => item.querySelector('[data-gfplus-control-icon]')?.getAttribute('data-gfplus-control-icon');
        const rank = (item) => {
            const index = order.indexOf(iconFor(item));
            return index < 0 ? order.length : index;
        };
        const listItems = [...originalItems].sort((a, b) => rank(a) - rank(b));
        let previousGroup = -1;
        listItems.forEach((item) => {
            const index = groups.findIndex((group) => group.includes(iconFor(item)));
            const group = index < 0 ? groups.length : index;
            item.toggleAttribute('data-gfplus-group-start', previousGroup !== -1 && previousGroup !== group);
            previousGroup = group;
        });
        const i18n = getUserNavI18n(getCurrentLocale());
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'gf-control-layout-toggle';
        button.setAttribute('aria-controls', panel.id);
        button.setAttribute('aria-label', i18n.controlPanelList);
        let layout = 'list';
        try {
            if (localStorage.getItem(CONTROL_PANEL_LAYOUT_KEY) === 'grid') layout = 'grid';
        } catch (error) { /* The view switch also works without storage. */ }
        const applyLayout = () => {
            const list = layout === 'list';
            panel.setAttribute('data-gfplus-control-layout', layout);
            // Move existing nodes so reading/tab order follows visual order, preserving handlers.
            panel.append(...(list ? listItems : originalItems));
            button.setAttribute('aria-pressed', String(list));
            button.title = list ? i18n.controlPanelGrid : i18n.controlPanelList;
            button.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true">${list
                ? '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'
                : '<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>'}</svg>`;
        };
        button.addEventListener('click', () => {
            layout = layout === 'grid' ? 'list' : 'grid';
            applyLayout();
            try {
                localStorage.setItem(CONTROL_PANEL_LAYOUT_KEY, layout);
            } catch (error) { /* Keep the selected layout for the current page. */ }
        });
        header.appendChild(button);
        applyLayout();
    };

    const USER_NAV_ICONS = {
        edit: `
            <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
            </svg>
        `,
        settings: `
            <svg viewBox="0 0 512 512" fill="currentColor" aria-hidden="true">
                <path d="M217.6,499.2v-55.279c-23.97-4.89-46.908-14.387-67.328-27.887l-39.091,39.083l-54.298-54.298
                    l39.083-39.091c-13.5-20.429-22.997-43.366-27.887-67.328H12.8v-76.8h55.279
                    c4.89-23.97,14.387-46.908,27.887-67.328l-39.083-39.091l54.298-54.306
                    l39.091,39.091c20.42-13.5,43.358-22.997,67.328-27.887V12.8h76.8v55.279
                    c23.97,4.89,46.908,14.387,67.328,27.887l39.091-39.091l54.298,54.306
                    l-39.083,39.091c13.5,20.429,22.997,43.366,27.887,67.328H499.2v76.8h-55.279
                    c-4.89,23.97-14.387,46.908-27.887,67.328l39.083,39.091l-54.298,54.298
                    l-39.091-39.083c-20.429,13.5-43.366,22.997-67.328,27.887V499.2H217.6z
                    M256,140.8c-63.522,0-115.2,51.678-115.2,115.2S192.478,371.2,256,371.2
                    S371.2,319.522,371.2,256S319.522,140.8,256,140.8z"/>
            </svg>
        `,
        signOut: `
            <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path>
                <polyline points="16 17 21 12 16 7"></polyline>
                <line x1="21" y1="12" x2="9" y2="12"></line>
            </svg>
        `
    };

    const parseUserProfileHref = (href) => {
        const match = String(href || '').match(/\/([a-z]{2,3}(?:-(?:[A-Z]{2}|[0-9]{3}))?)\/users\/(\d+)-/);
        return match ? { locale: match[1], userId: match[2] } : null;
    };

    const buildUserPanelHtml = (type, locale, userId, i18n) => type === 'edit'
        ? `
            <a href="/${locale}/script_versions/new">${i18n.submitScript}</a>
            <a href="/${locale}/script_versions/new?language=css">${i18n.submitStyle}</a>
            <div class="gf-user-panel-separator"></div>
            <a href="/${locale}/users/${userId}/sets/new">${i18n.submitSet}</a>
            <a href="/${locale}/users/webhook-info">${i18n.webhookInfo}</a>
            <div class="gf-user-panel-separator"></div>
            <a href="/${locale}/import">${i18n.importScripts}</a>
        `
        : `
            <a href="/${locale}/users/edit">${i18n.editProfile}</a>
            <a href="/${locale}/users/edit_sign_in">${i18n.editSignIn}</a>
            <div class="gf-user-panel-separator"></div>
            <a href="/${locale}/users/${userId}/notifications">${i18n.viewNotifications}</a>
            <a href="/${locale}/users/${userId}/notification_settings">${i18n.notificationSettings}</a>
            <div class="gf-user-panel-separator"></div>
            <a href="/${locale}/users/edit_account_deletion">${i18n.deleteAccount}</a>
        `;

    const createUserPanelControl = (type, locale, userId, i18n, mobile = false) => {
        const icon = document.createElement('span');
        icon.className = type === 'settings'
            ? 'gf-user-icon gf-user-icon--settings gf-user-icon--settings--hover'
            : `gf-user-icon${mobile ? ' gf-mobile-edit-icon' : ''}`;
        icon.setAttribute('data-panel', type);
        icon.innerHTML = USER_NAV_ICONS[type];

        const panel = document.createElement('div');
        panel.className = `gf-user-panel${mobile ? ' gf-mobile-user-panel' : ''}`;
        panel.setAttribute('data-panel-type', type);
        panel.innerHTML = buildUserPanelHtml(type, locale, userId, i18n);

        if (!mobile) {
            icon.appendChild(panel);
        }

        return { icon, panel };
    };

    const createSignOutControl = (source, mobile = false) => {
        const link = document.createElement('a');
        link.className = `gf-user-icon${mobile ? ' gf-mobile-sign-out-icon' : ''}`;
        link.href = source.href;
        link.rel = source.rel || 'nofollow';
        if (source.method) {
            link.setAttribute('data-method', source.method);
        }
        link.innerHTML = USER_NAV_ICONS.signOut;
        return link;
    };

    const bindUserPanelControls = (controls) => {
        let activeControl = null;

        const closePanels = () => {
            controls.forEach(({ icon, panel }) => {
                icon.classList.remove('active');
                panel.classList.remove('active');
            });
            activeControl = null;
        };

        controls.forEach((control) => {
            control.icon.addEventListener('click', (event) => {
                event.stopPropagation();
                const shouldOpen = !control.panel.classList.contains('active');
                closePanels();
                if (shouldOpen) {
                    control.icon.classList.add('active');
                    control.panel.classList.add('active');
                    activeControl = control;
                }
            });
        });

        document.addEventListener('click', (event) => {
            if (activeControl && !controls.some(({ icon, panel }) => icon.contains(event.target) || panel.contains(event.target))) {
                closePanels();
            }
        });

        document.addEventListener('keydown', (event) => {
            if (event.key === 'Escape' && activeControl) {
                closePanels();
            }
        });
    };


    const initUserNavigation = () => {
        const navUserInfo = document.getElementById('nav-user-info');
        if (!navUserInfo) {
            return false;
        }

        if (navUserInfo.querySelector('.gf-user-nav-icons')) {
            return true;
        }

        const profileLink = navUserInfo.querySelector('.user-profile-link a');
        if (!profileLink) {
            return false;
        }

        const userIdentity = parseUserProfileHref(profileLink.getAttribute('href'));
        if (!userIdentity) {
            return false;
        }

        const { locale, userId } = userIdentity;
        const i18n = getUserNavI18n(locale);

        const signOutLink = navUserInfo.querySelector('.sign-out-link');
        if (signOutLink) {
            signOutLink.remove();
        }

        const iconsContainer = document.createElement('span');
        iconsContainer.className = 'gf-user-nav-icons';

        const editControl = createUserPanelControl('edit', locale, userId, i18n);
        const settingsControl = createUserPanelControl('settings', locale, userId, i18n);
        const signOutControl = createSignOutControl({
            href: `/${locale}/users/sign_out`,
            rel: 'nofollow',
            method: 'delete'
        });
        iconsContainer.append(editControl.icon, settingsControl.icon, signOutControl);

        const profileLinkSpan = navUserInfo.querySelector('.user-profile-link');
        if (profileLinkSpan.nextSibling) {
            navUserInfo.insertBefore(iconsContainer, profileLinkSpan.nextSibling);
        } else {
            navUserInfo.appendChild(iconsContainer);
        }

        bindUserPanelControls([editControl, settingsControl]);

        return true;
    };

    let mobileUserNameLayoutInitialized = false;
    const syncMobileUserNameLayout = (userMeta) => {
        const profileLink = userMeta?.querySelector('.user-profile-link a');
        if (!profileLink) {
            return;
        }

        userMeta.toggleAttribute(
            'data-gfplus-user-name-truncated',
            profileLink.scrollWidth > profileLink.clientWidth + 1
        );
    };

    const initMobileUserNameLayout = (userMeta) => {
        syncMobileUserNameLayout(userMeta);
        if (mobileUserNameLayoutInitialized) {
            return;
        }

        mobileUserNameLayoutInitialized = true;
        window.addEventListener('resize', () => syncMobileUserNameLayout(userMeta), { passive: true });
        if (typeof ResizeObserver === 'function') {
            const observer = new ResizeObserver(() => syncMobileUserNameLayout(userMeta));
            observer.observe(userMeta);
            const profileLink = userMeta.querySelector('.user-profile-link a');
            if (profileLink) {
                observer.observe(profileLink);
            }
        }
    };

    const initMobileUserNavigation = () => {
        const mobileUserItem = document.querySelector('#mobile-nav li.multi-link-nav');
        if (!mobileUserItem) {
            return false;
        }

        if (mobileUserItem.querySelector('#gf-mobile-user-actions')) {
            initMobileUserNameLayout(document.getElementById('gf-mobile-user-meta'));
            return true;
        }

        const profileLinkSpan = mobileUserItem.querySelector('.user-profile-link');
        const profileLink = profileLinkSpan?.querySelector('a');
        const signOutContainer = mobileUserItem.querySelector('.sign-out-link');
        if (!profileLink || !signOutContainer) {
            return false;
        }

        const userIdentity = parseUserProfileHref(profileLink.getAttribute('href'));
        if (!userIdentity) {
            return false;
        }

        const { locale, userId } = userIdentity;
        const i18n = getUserNavI18n(locale);
        const signOutAnchor = signOutContainer.querySelector('a');
        if (!signOutAnchor) {
            return false;
        }

        const userRow = document.createElement('div');
        userRow.id = 'gf-mobile-user-row';

        const actions = document.createElement('span');
        actions.id = 'gf-mobile-user-actions';

        const editControl = createUserPanelControl('edit', locale, userId, i18n, true);
        const settingsControl = createUserPanelControl('settings', locale, userId, i18n, true);
        const signOutControl = createSignOutControl({
            href: signOutAnchor.href,
            rel: signOutAnchor.getAttribute('rel'),
            method: signOutAnchor.getAttribute('data-method')
        }, true);
        actions.append(editControl.icon, settingsControl.icon, signOutControl);

        const userMeta = document.createElement('div');
        userMeta.id = 'gf-mobile-user-meta';
        userMeta.appendChild(profileLinkSpan);

        const mobileThemeSwitch = document.getElementById('gf-mobile-theme-switch');
        const mobileThemeSwitchItem = document.getElementById('gf-mobile-theme-switch-item');
        if (mobileThemeSwitch) {
            mobileThemeSwitch.style.marginTop = '0';
            mobileThemeSwitch.style.marginRight = '0';
            mobileThemeSwitch.style.marginLeft = '0';
            userMeta.appendChild(mobileThemeSwitch);
        }

        if (mobileThemeSwitchItem) {
            mobileThemeSwitchItem.remove();
        }

        userRow.appendChild(userMeta);
        userRow.appendChild(actions);

        signOutContainer.remove();
        mobileUserItem.prepend(userRow);
        mobileUserItem.append(editControl.panel, settingsControl.panel);
        bindUserPanelControls([editControl, settingsControl]);
        initMobileUserNameLayout(userMeta);

        return true;
    };

    // Lightbox And Image Zoom
    const STANDALONE_LIGHTBOX_IMAGE_ATTR = 'data-gfplus-standalone-lightbox';
    let lightboxScrollLockObserver = null;
    let lightboxScrollPreventInitialized = false;
    let standaloneLightboxObserver = null;
    let lightboxZoomImage = null;
    let lightboxZoomImageSource = '';
    let lightboxZoomState = {
        scale: 1,
        x: 0,
        y: 0
    };
    let lightboxDragState = null;
    let lightboxPinchState = null;

    const clampLightboxZoomValue = (value, min, max) => Math.max(min, Math.min(max, value));

    const constrainLightboxPan = () => {
        if (!lightboxZoomImage || lightboxZoomState.scale <= 1) {
            lightboxZoomState.x = 0;
            lightboxZoomState.y = 0;
            return;
        }

        const maxX = (lightboxZoomImage.clientWidth * (lightboxZoomState.scale - 1)) / 2;
        const maxY = (lightboxZoomImage.clientHeight * (lightboxZoomState.scale - 1)) / 2;
        lightboxZoomState.x = clampLightboxZoomValue(lightboxZoomState.x, -maxX, maxX);
        lightboxZoomState.y = clampLightboxZoomValue(lightboxZoomState.y, -maxY, maxY);
    };

    const applyLightboxImageZoom = () => {
        if (!lightboxZoomImage) {
            return;
        }

        constrainLightboxPan();
        const zoomed = lightboxZoomState.scale > 1.01;
        lightboxZoomImage.classList.toggle('gfplus-lightbox-zoomed', zoomed);
        lightboxZoomImage.style.transform = zoomed
            ? `translate3d(${lightboxZoomState.x}px, ${lightboxZoomState.y}px, 0) scale(${lightboxZoomState.scale})`
            : '';
    };

    const resetLightboxImageZoom = () => {
        if (!lightboxZoomImage) {
            return;
        }

        lightboxZoomState = { scale: 1, x: 0, y: 0 };
        lightboxDragState = null;
        lightboxPinchState = null;
        lightboxZoomImage.classList.remove('gfplus-lightbox-zoomed', 'gfplus-lightbox-dragging');
        lightboxZoomImage.style.transform = '';
    };

    const setLightboxImageZoom = (scale, focalPoint = null) => {
        const previousScale = lightboxZoomState.scale;
        const nextScale = clampLightboxZoomValue(scale, 1, 4);

        if (lightboxZoomImage && focalPoint && previousScale > 0) {
            const rect = lightboxZoomImage.getBoundingClientRect();
            const imageCenterX = rect.left + rect.width / 2;
            const imageCenterY = rect.top + rect.height / 2;
            const scaleRatio = nextScale / previousScale;
            lightboxZoomState.x += (focalPoint.x - imageCenterX) * (1 - scaleRatio);
            lightboxZoomState.y += (focalPoint.y - imageCenterY) * (1 - scaleRatio);
        }

        lightboxZoomState.scale = nextScale;
        if (lightboxZoomState.scale <= 1.01) {
            lightboxZoomState = { scale: 1, x: 0, y: 0 };
        }
        applyLightboxImageZoom();
    };

    const getTouchDistance = (touches) => {
        const dx = touches[0].clientX - touches[1].clientX;
        const dy = touches[0].clientY - touches[1].clientY;
        return Math.hypot(dx, dy);
    };

    const getTouchCenter = (touches) => ({
        x: (touches[0].clientX + touches[1].clientX) / 2,
        y: (touches[0].clientY + touches[1].clientY) / 2
    });

    const handleLightboxImageWheel = (event) => {
        if (!root.classList.contains(LIGHTBOX_SCROLL_LOCK_CLASS)) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();
        const factor = event.deltaY < 0 ? 1.14 : 0.88;
        setLightboxImageZoom(lightboxZoomState.scale * factor, {
            x: event.clientX,
            y: event.clientY
        });
    };

    const handleLightboxImageDoubleClick = (event) => {
        event.preventDefault();
        event.stopPropagation();
        setLightboxImageZoom(lightboxZoomState.scale > 1.01 ? 1 : 2.4, {
            x: event.clientX,
            y: event.clientY
        });
    };

    const stopLightboxImageClickClose = (event) => {
        event.stopPropagation();
    };

    const handleLightboxImagePointerDown = (event) => {
        if (event.pointerType === 'touch' || lightboxZoomState.scale <= 1.01) {
            return;
        }

        event.preventDefault();
        lightboxDragState = {
            pointerId: event.pointerId,
            startX: event.clientX,
            startY: event.clientY,
            x: lightboxZoomState.x,
            y: lightboxZoomState.y
        };
        lightboxZoomImage?.classList.add('gfplus-lightbox-dragging');
        lightboxZoomImage?.setPointerCapture?.(event.pointerId);
    };

    const handleLightboxImagePointerMove = (event) => {
        if (!lightboxDragState || lightboxDragState.pointerId !== event.pointerId) {
            return;
        }

        event.preventDefault();
        lightboxZoomState.x = lightboxDragState.x + event.clientX - lightboxDragState.startX;
        lightboxZoomState.y = lightboxDragState.y + event.clientY - lightboxDragState.startY;
        applyLightboxImageZoom();
    };

    const endLightboxImagePointerDrag = (event) => {
        if (!lightboxDragState || lightboxDragState.pointerId !== event.pointerId) {
            return;
        }

        lightboxZoomImage?.releasePointerCapture?.(event.pointerId);
        lightboxZoomImage?.classList.remove('gfplus-lightbox-dragging');
        lightboxDragState = null;
    };

    const handleLightboxImageTouchStart = (event) => {
        if (event.touches.length === 2) {
            lightboxPinchState = {
                distance: getTouchDistance(event.touches),
                scale: lightboxZoomState.scale
            };
            return;
        }

        if (event.touches.length === 1 && lightboxZoomState.scale > 1.01) {
            lightboxDragState = {
                startX: event.touches[0].clientX,
                startY: event.touches[0].clientY,
                x: lightboxZoomState.x,
                y: lightboxZoomState.y
            };
        }
    };

    const handleLightboxImageTouchMove = (event) => {
        if (event.touches.length === 2 && lightboxPinchState) {
            event.preventDefault();
            event.stopPropagation();
            const nextScale = lightboxPinchState.scale * (getTouchDistance(event.touches) / lightboxPinchState.distance);
            setLightboxImageZoom(nextScale, getTouchCenter(event.touches));
            return;
        }

        if (event.touches.length === 1 && lightboxDragState && lightboxZoomState.scale > 1.01) {
            event.preventDefault();
            event.stopPropagation();
            lightboxZoomState.x = lightboxDragState.x + event.touches[0].clientX - lightboxDragState.startX;
            lightboxZoomState.y = lightboxDragState.y + event.touches[0].clientY - lightboxDragState.startY;
            applyLightboxImageZoom();
        }
    };

    const handleLightboxImageTouchEnd = () => {
        lightboxDragState = null;
        lightboxPinchState = null;
        lightboxZoomImage?.classList.remove('gfplus-lightbox-dragging');
    };

    const bindLightboxImageZoom = () => {
        const openLightbox = document.querySelector('.lum-lightbox.lum-open');
        const image = openLightbox?.querySelector('.lum-img, .lum-lightbox-inner img, img');
        const imageSource = image?.currentSrc || image?.src || '';
        if (!image) {
            return;
        }

        if (image === lightboxZoomImage && imageSource === lightboxZoomImageSource) {
            return;
        }

        resetLightboxImageZoom();
        lightboxZoomImage = image;
        lightboxZoomImageSource = imageSource;
        lightboxZoomImage.classList.add('gfplus-lightbox-zoomable');
        if (lightboxZoomImage.dataset.gfplusZoomBound !== 'true') {
            lightboxZoomImage.dataset.gfplusZoomBound = 'true';
            lightboxZoomImage.addEventListener('click', stopLightboxImageClickClose);
            lightboxZoomImage.addEventListener('wheel', handleLightboxImageWheel, { passive: false });
            lightboxZoomImage.addEventListener('dblclick', handleLightboxImageDoubleClick);
            lightboxZoomImage.addEventListener('pointerdown', handleLightboxImagePointerDown);
            lightboxZoomImage.addEventListener('pointermove', handleLightboxImagePointerMove);
            lightboxZoomImage.addEventListener('pointerup', endLightboxImagePointerDrag);
            lightboxZoomImage.addEventListener('pointercancel', endLightboxImagePointerDrag);
            lightboxZoomImage.addEventListener('touchstart', handleLightboxImageTouchStart, { passive: false });
            lightboxZoomImage.addEventListener('touchmove', handleLightboxImageTouchMove, { passive: false });
            lightboxZoomImage.addEventListener('touchend', handleLightboxImageTouchEnd);
            lightboxZoomImage.addEventListener('touchcancel', handleLightboxImageTouchEnd);
        }
    };

